<div class="fuel-row"><div class="row g-3"><div class="col-md-3"><label class="form-label" for="fuels[{{ $i }}][fuel_type_id]">Jenis BBM</label><select name="fuels[{{ $i }}][fuel_type_id]" class="form-select" id="fuels[{{ $i }}][fuel_type_id]">@foreach($fuelTypes as $f)<option value="{{ $f->id }}" {{ ($item['fuel_type_id']??null)==$f->id?'selected':'' }}>{{ $f->name }}</option>@endforeach</select></div><div class="col-md-3"><label class="form-label" for="fuels[{{ $i }}][fueling_location_id]">Tempat pengisian</label><select name="fuels[{{ $i }}][fueling_location_id]" class="form-select" id="fuels[{{ $i }}][fueling_location_id]"><option value="">Tidak diisi</option>@foreach($fuelLocations as $f)<option data-plant="{{ $f->plant_id }}" value="{{ $f->id }}" {{ ($item['fueling_location_id']??null)==$f->id?'selected':'' }}>{{ $f->name }}</option>@endforeach</select></div>@foreach(['quantity_filled'=>'Diisi','quantity_used'=>'Dipakai','quantity_remaining'=>'Sisa'] as $key=>$label)<div class="col-md-2"><label class="form-label" for="fuels[{{ $i }}][{{ $key }}]">{{ $label }} (liter)</label><input type="number" min="0" step="0.01" name="fuels[{{ $i }}][{{ $key }}]" value="{{ $item[$key]??0 }}" class="form-control" required id="fuels[{{ $i }}][{{ $key }}]"></div>@endforeach</div><button type="button" class="btn btn-link text-danger p-0 mt-2" onclick="this.closest('.fuel-row').remove()">Hapus BBM</button></div>